  formative_i18n = '{"en":["c. 1908: Married Aletha \"Lethe\" Henderson; began travelling and busking in Texas with Blind Lemon Jefferson. (Kilde: Wikipedia)","1918: Convicted of murder under the assumed name \"Walter Boyd\" in Sugar Land, Texas; sentenced to 30 years. (Kilde: Wikipedia)","1925: Released early after writing a clemency song to Texas Governor Pat Morris Neff. (Kilde: Wikipedia)","1930: Convicted of attempted homicide in Louisiana; sent to Angola State Penitentiary. (Kilde: Wikipedia)","July 1934: Recorded by John and Alan Lomax at Angola for the Library of Congress. (Kilde: Wikipedia)","January 1, 1935: Arrived in New York and became a sensation on the folk-revival circuit. (Kilde: Wikipedia)"],"no":["ca. 1908: Giftet seg med Aletha «Lethe» Henderson; begynte å reise og spille gatemusikk i Texas sammen med Blind Lemon Jefferson. (Kilde: Wikipedia)","1918: Dømt for drap under det antatte navnet «Walter Boyd» i Sugar Land, Texas; fikk 30 år. (Kilde: Wikipedia)","1925: Løslatt tidlig etter å ha skrevet en benådningssang til Texas-guvernør Pat Morris Neff. (Kilde: Wikipedia)","1930: Dømt for drapsforsøk i Louisiana; sendt til Angola State Penitentiary. (Kilde: Wikipedia)","Juli 1934: Spilt inn av John og Alan Lomax på Angola for Kongressbiblioteket. (Kilde: Wikipedia)","1. januar 1935: Ankom New York og ble en sensasjon på folkemusikk-scenen. (Kilde: Wikipedia)"]}',
  instruments_i18n = '{"en":[{"category":"Gitar","name":"Twelve-string Stella guitar","years":"1930s–1949","note":"Unusually long scale length requiring a trapeze tailpiece; strings typically tuned down, played with a driving thumb-picked bass line inspired by barrelhouse piano.","source":"Wikipedia"},{"category":"Annet","name":"Accordion, piano, mandolin, harmonica, violin","note":"Multi-instrumentalist; the accordion in particular features in his best-known 1940s photographs.","source":"Wikipedia"}],"no":[{"category":"Gitar","name":"Tolvstrenget Stella-gitar","years":"1930-tallet–1949","note":"Uvanlig lang mensur som krevde en trapes-strengeholder; strengene som regel stemt ned, spilt med en pådrivende, tommelplukket basslinje inspirert av barrelhouse-piano.","source":"Wikipedia"},{"category":"Annet","name":"Trekkspill, piano, mandolin, munnspill, fiolin","note":"Multiinstrumentalist; særlig trekkspillet går igjen på hans mest kjente fotografier fra 1940-tallet.","source":"Wikipedia"}]}',
  anecdotes_i18n = '{"en":["Wrote a personal clemency song directly to Texas Governor Pat Morris Neff, asking for release — he was freed the following year, though officials credited good behavior rather than the song itself. (Kilde: Wikipedia)","A 1938 recording of \"Scottsboro Boys\" captured him warning listeners to \"best stay woke, keep their eyes open\" — possibly the earliest audio recording of the phrase \"stay woke.\" (Kilde: Wikipedia)","George Harrison credited him as the reason the Beatles existed at all, via the Lonnie Donegan skiffle chain reaction. (Kilde: Wikipedia)"],"no":["Skrev en personlig benådningssang direkte til Texas-guvernør Pat Morris Neff og ba om løslatelse — han ble løslatt året etter, selv om tjenestemenn tilskrev god oppførsel fremfor selve sangen. (Kilde: Wikipedia)","En innspilling av «Scottsboro Boys» fra 1938 fanget ham mens han advarte lytterne om å «best stay woke, keep their eyes open» — trolig den tidligste lydinnspillingen av uttrykket «stay woke». (Kilde: Wikipedia)","George Harrison krediterte ham som grunnen til at Beatles i det hele tatt eksisterte, via Lonnie Donegans skiffle-kjedereaksjon. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Blind Lemon Jefferson","note":"Travelling and busking partner in Dallas''s Deep Ellum district before either had a record contract.","source":"Wikipedia"},{"name":"John & Alan Lomax","note":"Folklorists who recorded him at Angola Penitentiary in 1934 for the Library of Congress and later managed/toured with him — the partnership ended in dispute by 1935.","source":"Wikipedia"}],"no":[{"name":"Blind Lemon Jefferson","note":"Reise- og gatemusikk-partner i Dallas'' Deep Ellum-strøk før noen av dem hadde en platekontrakt.","source":"Wikipedia"},{"name":"John & Alan Lomax","note":"Folklorister som spilte ham inn på Angola-fengselet i 1934 for Kongressbiblioteket og senere styrte/turnerte med ham — samarbeidet endte i konflikt innen 1935.","source":"Wikipedia"}]}',
