  formative_i18n = '{"en":["Age ~10: Built himself a fiddle from a cigar box, learning from his uncle Jerry Belcher. (Kilde: Wikipedia)","c. 1920: Moved to Chicago and switched from fiddle to guitar, taught by Papa Charlie Jackson. (Kilde: Wikipedia)","1927: First record released, \"House Rent Stomp\" / \"Big Bill Blues,\" on Paramount. (Kilde: Wikipedia)","1947: Wrote \"Black, Brown and White\"; the label held it back from release until 1951 as too provocative. (Kilde: Wikipedia)","1951: First European tour, drawing standing ovations across the continent. (Kilde: Wikipedia)"],"no":["Rundt 10 år: Bygde seg selv en fele av en sigarkasse, og lærte av onkelen Jerry Belcher. (Kilde: Wikipedia)","ca. 1920: Flyttet til Chicago og byttet fra fele til gitar, lært opp av Papa Charlie Jackson. (Kilde: Wikipedia)","1927: Første plate utgitt, «House Rent Stomp» / «Big Bill Blues», på Paramount. (Kilde: Wikipedia)","1947: Skrev «Black, Brown and White»; selskapet holdt den tilbake fra utgivelse til 1951 som for provoserende. (Kilde: Wikipedia)","1951: Første Europa-turné, med stående applaus over hele kontinentet. (Kilde: Wikipedia)"]}',
  anecdotes_i18n = '{"en":["Long claimed to have served in World War I, but biographer Bob Riesman established he was only 14 when the U.S. entered the war and never actually enlisted. (Kilde: Wikipedia)","\"Black, Brown and White\" (written 1947) was considered too provocative by record labels and held back from release for four years. (Kilde: Wikipedia)","By 1942 he had recorded 224 songs, making him, by most counts, the second-most prolific blues artist of the entire prewar recording era. (Kilde: Wikipedia)"],"no":["Hevdet lenge å ha tjenestegjort i første verdenskrig, men biograf Bob Riesman fastslo at han bare var 14 år da USA gikk inn i krigen, og aldri faktisk vervet seg. (Kilde: Wikipedia)","«Black, Brown and White» (skrevet 1947) ble ansett som for provoserende av plateselskapene og holdt tilbake fra utgivelse i fire år. (Kilde: Wikipedia)","Innen 1942 hadde han spilt inn 224 sanger, noe som ifølge de fleste tellinger gjorde ham til den nest mest produktive bluesartisten i hele førkrigstidens innspillingsæra. (Kilde: Wikipedia)"]}',
  collaborators_i18n = '{"en":[{"name":"Papa Charlie Jackson","note":"Veteran minstrel performer who taught Broonzy guitar after his move to Chicago c. 1920.","source":"Wikipedia"},{"name":"Washboard Sam","note":"Half-brother; Broonzy composed many of his songs and played guitar on most of his recordings.","source":"Wikipedia"},{"name":"Jazz Gillum","note":"Harmonica player who recorded alongside Broonzy, including on \"Key to the Highway.\"","source":"Wikipedia"},{"name":"Tampa Red","note":"Close working collaborator through the 1930s–40s Chicago blues scene.","source":"Wikipedia"}],"no":[{"name":"Papa Charlie Jackson","note":"Erfaren minstrel-utøver som lærte Broonzy gitar etter flyttingen til Chicago ca. 1920.","source":"Wikipedia"},{"name":"Washboard Sam","note":"Halvbror; Broonzy komponerte mange av sangene hans og spilte gitar på de fleste innspillingene hans.","source":"Wikipedia"},{"name":"Jazz Gillum","note":"Munnspillspiller som spilte inn sammen med Broonzy, deriblant på «Key to the Highway».","source":"Wikipedia"},{"name":"Tampa Red","note":"Tett samarbeidspartner gjennom 1930- og 40-tallets Chicago-bluesmiljø.","source":"Wikipedia"}]}',
